using System.ComponentModel;
using System.Net;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration -----------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Build the chat client through MEAI abstraction --------------------------
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Tools -------------------------------------------------------------------
var notebook = new ResearchNotebook();
var tools = new AITool[]
{
    AIFunctionFactory.Create(SearchWeb),
    AIFunctionFactory.Create(
        notebook.SaveNote,
        nameof(ResearchNotebook.SaveNote),
        "Save a research note with a title and body. Call this to record important findings."),
    AIFunctionFactory.Create(
        notebook.GetNotes,
        nameof(ResearchNotebook.GetNotes),
        "Retrieve all saved research notes so far."),
};

// --- Agent setup (Microsoft Agent Framework) ---------------------------------
const string instructions = """
    You are a research assistant. Given a topic, you:
    1. Search the web for relevant information (multiple queries for breadth).
    2. Save important findings as notes using the SaveNote tool.
    3. After gathering enough information, retrieve your notes and produce a
       concise, well-structured summary with key facts and source URLs.

    Always cite your sources. Aim for 3-5 searches before summarizing.
    """;

var innerAgent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "Researches a topic by searching the web and summarizing findings.",
    tools: tools);

var agent = new LoopAgent(
    innerAgent,
    new CompletionMarkerLoopEvaluator(),
    new LoopAgentOptions { MaxIterations = 10 });

// --- Main interaction loop ---------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║       🔍 AI Research Agent               ║");
Console.WriteLine("║  Type a topic to research, or 'quit'.    ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

await using var session = await agent.CreateSessionAsync();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
    {
        Console.WriteLine("Goodbye!");
        break;
    }

    notebook.Clear();
    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching… (the agent will search the web and take notes)");
    Console.ResetColor();

    try
    {
        var runOptions = new ChatClientAgentRunOptions(
            new ChatOptions { Temperature = 0f, MaxOutputTokens = 4096 });

        var response = await agent.RunAsync(
            $"Research the following topic and provide a comprehensive summary: {topic}",
            session,
            runOptions);

        Console.WriteLine();
        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine("═══ Research Summary ═══");
        Console.ResetColor();
        Console.WriteLine(response.Text);
        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }
}

// =============================================================================
// Tools
// =============================================================================

[Description("Search the web for information on a query. Returns a list of result snippets with URLs.")]
static async Task<string> SearchWeb(
    [Description("The search query string")] string query)
{
    Console.ForegroundColor = ConsoleColor.Yellow;
    Console.WriteLine($"  🔎 Searching: \"{query}\"");
    Console.ResetColor();

    try
    {
        using var http = new HttpClient();
        var encoded = WebUtility.UrlEncode(query);
        var url = $"https://html.duckduckgo.com/html/?q={encoded}";

        var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.UserAgent.ParseAdd(
            "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

        var html = await http.SendAsync(request);
        var content = await html.Content.ReadAsStringAsync();

        var results = ParseDuckDuckGoResults(content);
        if (results.Count == 0)
            return "No results found for this query.";

        return string.Join("\n\n", results.Take(5));
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}";
    }
}

static List<string> ParseDuckDuckGoResults(string html)
{
    var results = new List<string>();
    var snippetMarker = "result__snippet";
    var titleMarker = "result__a";
    var hrefMarker = "result__url";

    var pos = 0;
    while (pos < html.Length && results.Count < 5)
    {
        // Find next result snippet
        var snippetIdx = html.IndexOf(snippetMarker, pos, StringComparison.Ordinal);
        if (snippetIdx < 0) break;

        var title = ExtractTagContent(html, titleMarker, pos, snippetIdx);
        var snippet = ExtractTagContent(html, snippetMarker, snippetIdx, 
            Math.Min(snippetIdx + 2000, html.Length));
        var href = ExtractHref(html, hrefMarker, pos, snippetIdx + 2000);

        if (!string.IsNullOrWhiteSpace(snippet))
        {
            var entry = $"**{WebUtility.HtmlDecode(title ?? "Result")}**\n" +
                        $"{WebUtility.HtmlDecode(snippet)}\n" +
                        $"URL: {WebUtility.HtmlDecode(href ?? "N/A")}";
            results.Add(entry);
        }

        pos = snippetIdx + snippetMarker.Length;
    }

    return results;
}

static string? ExtractTagContent(string html, string cssClass, int searchStart, int searchEnd)
{
    var end = Math.Min(searchEnd, html.Length);
    var classIdx = html.IndexOf(cssClass, searchStart, StringComparison.Ordinal);
    if (classIdx < 0 || classIdx >= end) return null;

    var gtIdx = html.IndexOf('>', classIdx);
    if (gtIdx < 0) return null;

    var closeIdx = html.IndexOf('<', gtIdx + 1);
    if (closeIdx < 0) return null;

    return html[(gtIdx + 1)..closeIdx].Trim();
}

static string? ExtractHref(string html, string cssClass, int searchStart, int searchEnd)
{
    var end = Math.Min(searchEnd, html.Length);
    var classIdx = html.IndexOf(cssClass, searchStart, StringComparison.Ordinal);
    if (classIdx < 0 || classIdx >= end) return null;

    var hrefIdx = html.LastIndexOf("href=\"", classIdx, StringComparison.Ordinal);
    if (hrefIdx < 0)
    {
        hrefIdx = html.IndexOf("href=\"", classIdx, StringComparison.Ordinal);
        if (hrefIdx < 0 || hrefIdx >= end) return null;
    }

    var start = hrefIdx + 6;
    var quoteEnd = html.IndexOf('"', start);
    if (quoteEnd < 0) return null;

    return html[start..quoteEnd];
}

