// Research Notebook
// =============================================================================

sealed class ResearchNotebook
{
    private readonly List<(string Title, string Body)> _notes = [];

    public string SaveNote(
        [Description("A short title for this note")] string title,
        [Description("The note body with facts and source URLs")] string body)
    {
        _notes.Add((title, body));
        Console.ForegroundColor = ConsoleColor.Magenta;
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        Console.ResetColor();
        return $"Note #{_notes.Count} saved: \"{title}\"";
    }

    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"--- Note #{i + 1}: {n.Title} ---\n{n.Body}"));
    }

    public void Clear() => _notes.Clear();
}

