 [Description("Search the web for information on a query. Returns a list of result snippets with URLs.")]
 static async Task<string> SearchWeb(
     [Description("The search query string")] string query)
 {
     Console.ForegroundColor = ConsoleColor.Yellow;
     Console.WriteLine($"  🔎 Searching: \"{query}\"");
     Console.ResetColor();

     try
     {
         using var http = new HttpClient();
         var encoded = WebUtility.UrlEncode(query);
         var url = $"https://html.duckduckgo.com/html/?q={encoded}";

         var request = new HttpRequestMessage(HttpMethod.Get, url);
         request.Headers.UserAgent.ParseAdd(
             "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

         var html = await http.SendAsync(request);
         var content = await html.Content.ReadAsStringAsync();

         var results = ParseDuckDuckGoResults(content);
         if (results.Count == 0)
             return "No results found for this query.";

         return string.Join("\n\n", results.Take(5));
     }
     catch (Exception ex)
     {
         return $"Search failed: {ex.Message}";
     }
 }

 static List<string> ParseDuckDuckGoResults(string html)
 {
     var results = new List<string>();
     var snippetMarker = "result__snippet";
     var titleMarker = "result__a";
     var hrefMarker = "result__url";

     var pos = 0;
     while (pos < html.Length && results.Count < 5)
     {
         // Find next result snippet
         var snippetIdx = html.IndexOf(snippetMarker, pos, StringComparison.Ordinal);
         if (snippetIdx < 0) break;

         var title = ExtractTagContent(html, titleMarker, pos, snippetIdx);
         var snippet = ExtractTagContent(html, snippetMarker, snippetIdx, 
             Math.Min(snippetIdx + 2000, html.Length));
         var href = ExtractHref(html, hrefMarker, pos, snippetIdx + 2000);

         if (!string.IsNullOrWhiteSpace(snippet))
         {
             var entry = $"**{WebUtility.HtmlDecode(title ?? "Result")}**\n" +
                         $"{WebUtility.HtmlDecode(snippet)}\n" +
                         $"URL: {WebUtility.HtmlDecode(href ?? "N/A")}";
             results.Add(entry);
         }

         pos = snippetIdx + snippetMarker.Length;
     }

     return results;
 }

 static string? ExtractTagContent(string html, string cssClass, int searchStart, int searchEnd)
 {
     var end = Math.Min(searchEnd, html.Length);
     var classIdx = html.IndexOf(cssClass, searchStart, StringComparison.Ordinal);
     if (classIdx < 0 || classIdx >= end) return null;

     var gtIdx = html.IndexOf('>', classIdx);
     if (gtIdx < 0) return null;

     var closeIdx = html.IndexOf('<', gtIdx + 1);
     if (closeIdx < 0) return null;

     return html[(gtIdx + 1)..closeIdx].Trim();
 }

 static string? ExtractHref(string html, string cssClass, int searchStart, int searchEnd)
 {
     var end = Math.Min(searchEnd, html.Length);
     var classIdx = html.IndexOf(cssClass, searchStart, StringComparison.Ordinal);
     if (classIdx < 0 || classIdx >= end) return null;

     var hrefIdx = html.LastIndexOf("href=\"", classIdx, StringComparison.Ordinal);
     if (hrefIdx < 0)
     {
         hrefIdx = html.IndexOf("href=\"", classIdx, StringComparison.Ordinal);
         if (hrefIdx < 0 || hrefIdx >= end) return null;
     }

     var start = hrefIdx + 6;
     var quoteEnd = html.IndexOf('"', start);
     if (quoteEnd < 0) return null;

     return html[start..quoteEnd];
 }

